<template><Card class="s1-ui"><header class="ui-header"><div><h2>{{g.name||'商品与库存详情'}}</h2><p>{{g.storeName||'店铺名称未提供'}} <StatusTag :value="g.reviewStatus"/><StatusTag :value="g.marketStatus"/></p><p class="ui-meta">商品 {{g.id}} · 内容v{{g.contentVersion}} · 数据v{{g.version}}</p></div><div class="ui-actions"><Button @click="back">返回商品列表</Button><Button :loading="loading" @click="reload">重新读取</Button></div></header><Alert v-if="error" type="error">{{error}}</Alert><Spin v-if="loading"/><template v-if="value"><Alert v-if="historical" type="warning">正在查看送审内容 v{{currentRevision}}，当前库存独立读取。<Button type="text" @click="currentRevision=null">返回当前内容</Button></Alert><DetailSection title="商品基本信息"><FieldRow label="名称" :value="c.name"/><FieldRow label="卖点" :value="c.subtitle"/><FieldRow label="店铺" :value="g.storeName"/><FieldRow label="类目" :value="c.categoryId===g.categoryId?g.categoryPath:c.categoryId?'该版本名称未提供（'+c.categoryId+'）':null"/><FieldRow label="单位" :value="c.unitId===g.unitId?g.unitName:c.unitId?'该版本名称未提供（'+c.unitId+'）':null"/><FieldRow label="品牌引用" :value="c.brandId?'品牌名称未提供（'+c.brandId+'）':null"/><FieldRow label="备注" :value="c.note" wide/><FieldRow label="内容批准版本" :value="g.approvedVersion"/><FieldRow label="更新时间（上海）" :value="date(g.updatedAt)"/></DetailSection><DetailSection title="图片与图文" :grid="false"><div class="ui-images"><ProductImage v-for="file in c.galleryFileIds||[]" :key="file" :goods-id="g.id" :file-id="file" :alt="g.name" large/></div><template v-for="(block,index) in c.detailBlocks||[]"><p v-if="block.type==='text'" :key="index" class="s2-copy">{{block.text}}</p><ProductImage v-else :key="index" :goods-id="g.id" :file-id="block.fileId" large/></template></DetailSection><DetailSection title="SKU、可售库存及占用" :grid="false"><SkuTable :rows="historical?selectedReview.submitted.skus:value.skus" :live="value.skus" :snapshot="historical" held/><p class="ui-note">A为当前可售数量，H为本期仍占用数量；人工目标A′保留H。此页只读，未核实占用不显示为0。</p></DetailSection><DetailSection title="履约与可售状态"><FieldRow label="商品支持" :value="(g.methods||[]).map(method).join(' / ')"/><FieldRow label="当前有效" :value="(g.effectiveMethods||[]).map(method).join(' / ')"/><FieldRow label="当前可售" :value="g.currentSaleable?'可售':'不可售'"/><FieldRow label="监管" :value="g.forcedOff?'监管下架':'未受管制'"/><FieldRow label="监管原因" :value="g.forcedReason" wide/><FieldRow label="不可售原因" :value="(g.saleabilityReasons||[]).map(label).join('、')" wide/></DetailSection><DetailSection title="内容审核历史" :grid="false"><HistoryTable :records="value.reviews" :columns="reviewColumns"><template slot="operations" slot-scope="{row}"><Button size="small" @click="currentRevision=row.contentVersion">查看内容 v{{row.contentVersion}}</Button></template></HistoryTable></DetailSection><DetailSection title="监管历史" :grid="false"><HistoryTable :records="value.regulationHistory" :columns="historyColumns"/></DetailSection><p class="ui-meta">当前内容与历史审核记录分别展示；本页不批准、改库存或改变付款状态。</p></template></Card></template>
<script>import {stage2UiRead} from '@/api/stage2-ui';import {managerSession} from '@/libs/manager-session';import FieldRow from '../p0-stage1/usability/components/FieldRow';import DetailSection from '../p0-stage1/usability/components/DetailSection';import StatusTag from '../p0-stage1/usability/components/StatusTag';import SkuTable from '../p0-stage1/usability/components/SkuTable';import HistoryTable from '../p0-stage1/usability/components/HistoryTable';import BaseImage from '../p0-stage1/usability/components/ProductImage';import {productImage} from './enabled';import {date,status as label} from '../p0-stage1/usability/display.cjs';import {returnLocation} from '../p0-stage1/usability/list-state.cjs';export default {components:{FieldRow,DetailSection,StatusTag,SkuTable,HistoryTable,ProductImage:productImage(BaseImage)},data:()=>({value:null,currentRevision:null,error:'',loading:false,ticket:0,reviewColumns:[{title:'内容版本',key:'contentVersion',width:110},{title:'时间（上海）',slot:'time',minWidth:170},{title:'审核结果',slot:'state',width:110},{title:'意见',key:'reason',minWidth:240},{title:'内容',slot:'operations',minWidth:150}],historyColumns:[{title:'时间（上海）',slot:'time',minWidth:170},{title:'动作',slot:'action',minWidth:120},{title:'原版本',key:'beforeVersion',width:100},{title:'新版本',key:'afterVersion',width:100},{title:'原因',key:'reason',minWidth:240}]}),computed:{g(){return this.value?.goods||{};},selectedReview(){return this.value?.reviews.find(r=>r.contentVersion===this.currentRevision);},historical(){return Boolean(this.selectedReview);},c(){return this.selectedReview?.submitted.content||this.value?.payload||{};}},mounted(){this.reload();},watch:{'$route.params.id'(){this.value=null;this.reload();}},beforeDestroy(){this.ticket++;},methods:{date,label,method(v){return {MERCHANT_DELIVERY:'商户配送',EXPRESS:'普通物流',COMMUNITY_PICKUP:'社区自提',STORE_REDEMPTION:'到店核销'}[v]||v;},back(){this.$router.push(returnLocation(this.$route.path,this.$route.query));},async reload(){const n=++this.ticket,scope=managerSession.snapshot();this.error='';this.loading=true;try{const v=await stage2UiRead('/'+this.$route.params.id);if(n===this.ticket&&managerSession.sameSession(scope))this.value=v;}catch(e){if(n===this.ticket){this.value=null;this.error=e.message;}}finally{if(n===this.ticket)this.loading=false;}}}};</script><style lang="scss">@import '../p0-stage1/usability/usability.scss';.s2-copy{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9}.ui-images{display:flex;flex-wrap:wrap;gap:12px}</style>
